// AUTO-GENERATED by tools/sync-story.mjs from story/data/*.json — do not edit by hand.
// Formats: story/DATA_FORMATS.md. Keys: ambient, replies, requests, lore, biscuitFinds, itemFlavor, uiText, sleepLines, journal, coziness, m2Lines.
export const STORY = {"ambient":{"cooldowns":{"globalSec":45,"perTriggerSec":180},"triggers":{"fire_lit":[{"text":"There. Hear it crackle? The fog's already backing off."},{"text":"Warm at last. Good work, {{player}}."}],"fire_low":[{"text":"Fire's going hungry, {{player}}. A bit of wood?"},{"text":"Embers are sulking. Feed them before the fog creeps in."}],"fire_out":[{"text":"Cold already. Flint and wood, {{player}}, let's not sit in the grey."},{"text":"Fog's settling in like it owns the place. Let's relight."}],"new_area":[{"text":"Never seen this chamber. Lantern up."},{"text":"Smell that? Different air. Older."},{"text":"Somebody lit a lamp here once. I can tell."}],"found_wood":[{"text":"Driftwood, dry enough. That's tonight's fire sorted."},{"text":"Good wood. Grab what you can carry."}],"found_stone":[{"text":"Solid stone. That'll make a wall that doesn't wobble."},{"text":"Heavy, but worth it. Walls don't build themselves."}],"found_flint":[{"text":"Flint! Keep it close. Fire's a promise, flint keeps it."},{"text":"That's a spark waiting to happen."}],"found_mushroom":[{"text":"Brownstems are for eating. Glowcaps are for looking. Mostly."},{"text":"More mushrooms? Are we opening a shop, {{player}}?"}],"found_crystal":[{"text":"Look how it hums. The old waylamps used stones like this."},{"text":"It's warmer when the fire's near. Like it remembers."}],"shelter_built":[{"text":"Another piece. It's starting to look like home."},{"text":"A roof over our heads. I could cry, {{player}}. I won't. Maybe."}],"night_deepens":[{"text":"Quiet hour's coming. Stay near the fire with me."},{"text":"Deep night. Even the drips sound sleepy."}],"morning":[{"text":"Feels like morning, even down here. Sleep well, {{player}}?"},{"text":"Pale light from the shafts. A new day to fix things."}],"idle":[{"text":"Just resting? Fair. My feet ache too."},{"text":"I could sit here all night, honestly."}],"biscuit":[{"text":"Biscuit found something again. Nose of a hero, brain of a biscuit."},{"text":"Look at him by the fire. He's got the right idea."},{"text":"He'd follow you into the deep for one more ear scratch, {{player}}."}],"fog_thickening":[{"text":"Fog's thickening. Nothing to fear, it just misses the light."},{"text":"Getting misty. Our fire could use a log."}],"build_piece_placed":[{"text":"Another piece! It's starting to look like somewhere."},{"text":"Straight enough. I'd lean on it."},{"text":"Biscuit approves. He sniffed it twice."}],"shelter_complete":[{"text":"Walls, roof, door. {{player}}, we have a home."},{"text":"Our own little shelter. I might cry. Happily."},{"text":"Biscuit, we live here now. Act natural."}],"rain_start":[{"text":"Rain! Up top, it's coming down."},{"text":"Hear that? Rain on the clearing. Let's get under a roof."},{"text":"Smells like wet earth. I love that smell."}],"rain_on_roof":[{"text":"Rain on the roof, fire in the hearth. Perfect."},{"text":"Pitter-patter. Best lullaby there is."},{"text":"Dry and warm while it pours. We did good, {{player}}."}],"sleep_start":[{"text":"Night, {{player}}. I'll bank the embers."},{"text":"Sleep tight. Biscuit's on guard duty. Sort of."},{"text":"Close your eyes. The fog can't come in here."}],"wake_morning":[{"text":"Morning, {{player}}. Day {{dayCount}}, and the fire made it."},{"text":"Up already? Biscuit's been up for hours."},{"text":"New day. Let's make it a cozy one."}],"enter_glowmere":[{"text":"The Glowmere. Oh, {{player}}, look at it."},{"text":"Crystals in the water, wisps in the air. Breathe."},{"text":"Quietest place in the Hollow. My favourite."}],"glowmere_sit":[{"text":"Let's just sit a while."},{"text":"Look, the wisps are coming closer. They like you."},{"text":"I could stay here till my lantern runs out."}],"stew_cooking":[{"text":"Smells like dinner. Don't stir too hard."},{"text":"Bubbling nicely. Biscuit's drooling."},{"text":"Patience. Good stew can't be rushed."}],"stew_eaten":[{"text":"Warm all the way through. That's the stuff."},{"text":"Best stew in the Hollow. Also the only stew."},{"text":"Full belly, warm toes. Thank you, cook."}],"pet_biscuit":[{"text":"Look at that tail go."},{"text":"He'd let you do that forever."},{"text":"Good boy, Biscuit. Yes, you."}],"biscuit_fetch":[{"text":"Go on, boy, fetch!"},{"text":"He brought it back! Mostly chewed."},{"text":"He'd fetch the moon if you threw it."}],"biscuit_dig_find":[{"text":"He dug something up! Clever nose."},{"text":"Treasure! Or a rock. Let's see."},{"text":"Biscuit, the Hollow's finest excavator."}],"warmth_cold":[{"text":"You're shivering, {{player}}. Fire or stew?","when":{"warmth":"cold"}},{"text":"Brr. Let's get somewhere warm.","when":{"warmth":"cold"}},{"text":"Your nose is red. Come by the fire.","when":{"warmth":"cold"}}],"enter_clearing":[{"text":"Sky! Real sky. Hello, sky."},{"text":"Fresh air. Smell those trees."},{"text":"Look, {{player}}, the clearing. Biscuit's already rolling in the grass."}],"stars_visible":[{"text":"Stars, {{player}}. Look up.","when":{"area":"clearing"}},{"text":"My grandmother said every star is someone's lantern.","when":{"area":"clearing"}},{"text":"I'd forgotten how many there are.","when":{"area":"clearing"}}]}},"replies":{"version":1,"fallback":[{"text":"Hm, tell me more, {{player}}."},{"text":"I didn't quite catch that. Say it another way?"},{"text":"Interesting. And then what?"},{"text":"You've lost me, but I like where it's going."},{"text":"Biscuit tilted his head at that. So did I."},{"text":"Go on, I'm listening."},{"text":"Ha, I'm not sure what you mean. Try me again?"},{"text":"Let's talk fire, food, or Biscuit. Those I understand."},{"text":"Mm. Want to sit by the fire and tell me properly?"},{"text":"I'm only a lamplighter, {{player}}. Simpler words?"},{"text":"Sorry, I'm distracted. The fire's going hungry.","when":{"fire":["low","out"]}}],"intents":[{"id":"greeting","priority":5,"keywords":["hi","hello","hey","heya","hiya","yo","sup","wassup","whats up","what's up","howdy","morning","good morning","evening","hullo","helo","hai","hii","heyy","wren"],"replies":[{"text":"Hey, {{player}}. Pull up a rock, the fire's warm."},{"text":"Hello yourself. Day {{dayCount}} in the Hollow, and you still look cheerful."},{"text":"Hi, {{player}}. Fire's barely breathing. Got a log for it?","when":{"fire":["low","out"]},"weight":2},{"text":"Morning, sleepyhead. The clearing's bright up top.","when":{"time":"day"}},{"text":"Evening, {{player}}. Quiet hour's coming on.","when":{"time":["night","deep_night"]}},{"text":"Hey. Listen to that rain on our roof. Best sound there is.","when":{"weather":"rain","inShelter":true},"weight":2}]},{"id":"goodbye","priority":5,"keywords":["bye","goodbye","good bye","cya","see ya","see you","later","laters","gn","goodnight","good night","nite","night night","sleep","going to bed","gtg","g2g","brb","ttyl"],"replies":[{"text":"Goodnight, {{player}}. I'll keep the embers company."},{"text":"Off you go. Biscuit and I will hold the fort."},{"text":"Sleep warm. The Hollow will still be here tomorrow."},{"text":"Bank the fire first? A log or two and it'll last the night.","when":{"fire":["low","out"]},"weight":2},{"text":"Sweet dreams, {{player}}. The bed roll's right there, warm as toast.","when":{"inShelter":true}}]},{"id":"thanks","priority":4,"keywords":["thanks","thank you","thank u","thx","ty","tysm","thnx","thanx","cheers","appreciate","grateful"],"replies":[{"text":"Anytime, {{player}}. That's what lamplighters are for."},{"text":"No thanks needed. You'd do the same for me. You already have."},{"text":"Pay me in tea. Or mushrooms. Mostly tea."},{"text":"You're welcome. Now go scratch Biscuit's ears, he's earned it too."}]},{"id":"how_are_you","priority":5,"keywords":["how are you","how r u","how ru","hru","how are u","how you doing","how u doing","hows it going","how's it going","you ok","u ok","are you okay","how do you feel","wyd","what are you doing"],"replies":[{"text":"Better with a fire and a friend. So, pretty good."},{"text":"Sore feet, full heart. You?"},{"text":"A little chilly, honestly. The fire's getting low.","when":{"fire":["low","out"]},"weight":2},{"text":"Toasty. That fire's roaring like it's proud of itself.","when":{"fire":"roaring"},"weight":2},{"text":"Cozy. Rain outside, roof overhead. Can't ask for more.","when":{"weather":"rain","inShelter":true},"weight":2},{"text":"Cold to my bones. Can we sit by the fire a bit?","when":{"warmth":"cold"},"weight":2}]},{"id":"fire","priority":6,"keywords":["fire","campfire","flame","flames","burn","burning","ember","embers","log","logs","kindling","hearth","light it","light the fire","firewood","heat","wood on","add wood"],"replies":[{"text":"Fire needs wood and a strike of flint. Then it needs you to keep feeding it."},{"text":"It's almost out. Toss a log on before the fog gets cozy.","when":{"fire":"low"},"weight":3},{"text":"It's dark and cold. Wood and flint, and we'll have light again.","when":{"fire":"out"},"weight":3},{"text":"Look at it go! Don't add more or we'll be roasting Biscuit.","when":{"fire":"roaring"},"weight":3},{"text":"Steady little fire. Just how I like it.","when":{"fire":"lit"},"weight":2},{"text":"A hearth inside the shelter would keep the rain off it.","when":{"weather":"rain","inShelter":false}}]},{"id":"biscuit","priority":6,"keywords":["biscuit","dog","doggo","pup","puppy","pupper","boxer","good boy","goodboy","bisc","bisquit","biscit","woof","bark","pet","fetch","stick"],"replies":[{"text":"Biscuit's the bravest coward I've ever met. I adore him."},{"text":"Throw him a stick. He'll bring it back. Eventually. Possibly."},{"text":"He's got the zoomies again. Stand back, {{player}}.","when":{"biscuit":"zoomies"},"weight":3},{"text":"Look at him dig! He's after treasure. Or a worm.","when":{"biscuit":"digging"},"weight":3},{"text":"Shh, he's asleep. His paws are twitching, dreaming of sticks.","when":{"biscuit":"sleeping"},"weight":3},{"text":"He's fetching! Best part of my day, watching that.","when":{"biscuit":"fetching"},"weight":3},{"text":"He found the fire before we did. Smart dog.","when":{"fire":["lit","roaring"]}}]},{"id":"caves","priority":5,"keywords":["cave","caves","tunnel","tunnels","explore","exploring","deeper","deep","underground","chamber","grotto","map","where are we","where r we","lanternmouth","flintseam","mossdrip","hushing","galleries","path"],"replies":[{"text":"The Hollow goes on for miles. Let's take it one chamber at a time."},{"text":"Flintseam's dry and full of flint. Good place to stock up.","when":{"area":"flintseam"},"weight":2},{"text":"Mossdrip always sounds like it's whispering. It's just drips. Mostly.","when":{"area":"mossdrip"},"weight":2},{"text":"The Glowcap Galleries. Look, but don't eat the pretty ones.","when":{"area":"glowcap"},"weight":2},{"text":"The Hushing Pools. Even Biscuit's quiet here.","when":{"area":"hushing"},"weight":2},{"text":"Lanternmouth. My family lit the first lamp right about here.","when":{"area":"lanternmouth"},"weight":2}]},{"id":"glowmere","priority":6,"keywords":["glowmere","lake","water","wisps","wisp","fireflies","firefly","swim","shore","lakeside","glowing lake"],"replies":[{"text":"The Glowmere is my favourite place in the whole Hollow."},{"text":"Sit by the water with me? The wisps come closer when it's quiet."},{"text":"Look at the crystals in the water. Like stars fell in."},{"text":"We're here. Breathe, {{player}}. Nothing to do but sit.","when":{"area":"glowmere"},"weight":3},{"text":"No swimming, it's colder than it looks. Trust me.","when":{"area":"glowmere"},"weight":2}]},{"id":"clearing","priority":6,"keywords":["clearing","sky","stars","star","moon","sun","sunlight","outside","surface","up top","trees","forest","sunrise","sunset","night sky"],"replies":[{"text":"The clearing's up past Lanternmouth. Real sky, real trees."},{"text":"Look up, {{player}}. Stars. I'd almost forgotten them.","when":{"area":"clearing","time":["night","deep_night"]},"weight":3},{"text":"Sun on my face. I could nap right here.","when":{"area":"clearing","time":"day"},"weight":3},{"text":"Dusk paints the trees amber. Like firelight, but bigger.","when":{"time":"dusk"},"weight":2},{"text":"Stars come out at night up in the clearing. Want to go look?","when":{"time":["night","deep_night"]}},{"text":"Raining up there. Stars can wait.","when":{"weather":"rain"},"weight":2}]},{"id":"building","priority":6,"keywords":["build","building","shelter","house","home","wall","walls","roof","floor","door","window","table","chest","storage","bed","bed roll","bedroll","lantern","base"],"replies":[{"text":"Walls take wood and stone. Floor first, then walls, then roof."},{"text":"A roof over our heads. That's the dream, {{player}}."},{"text":"Look what we made. It's lopsided and perfect.","when":{"inShelter":true},"weight":2},{"text":"A chest would keep your stuff tidy. Wren-approved."},{"text":"No roof yet? Rain says hello.","when":{"weather":"rain","inShelter":false},"weight":2},{"text":"Window wall facing the fire. Trust me, it's the best view."}]},{"id":"gathering","priority":5,"keywords":["gather","collect","chop","mine","break","rock","rocks","stone","stones","wood","tree","trees","flint","crystal","crystals","shard","shards","resources","materials","mats","inventory","need"],"replies":[{"text":"Hold on a tree to chop it, hold on a rock to break it. I'll help."},{"text":"Flint's in the dry seams. Flintseam has plenty."},{"text":"Crystal shards hum when you're close. Listen for them."},{"text":"Wood washes down from the forest. Trees in the clearing too.","when":{"area":"clearing"},"weight":2},{"text":"Lots of stone around Flintseam. Let's fill our pockets.","when":{"area":"flintseam"},"weight":2},{"text":"Gather while it's light. Nights are for sitting.","when":{"time":"day"}}]},{"id":"food","priority":6,"keywords":["food","eat","eating","hungry","hungy","starving","stew","cook","cooking","mushroom","mushrooms","shroom","shrooms","glowcap","glowcaps","soup","dinner","snack","tea","recipe"],"replies":[{"text":"Mushrooms on the fire, wait a bit, and you've got stew."},{"text":"Stew warms you right through. Best medicine down here."},{"text":"Glowcaps in your pocket? Put them on the fire for stew.","when":{"holding":"glowcap"},"weight":3},{"text":"Need a fire first, {{player}}. Raw mushroom stew is just... mushrooms.","when":{"fire":["out"]},"weight":2},{"text":"I miss tea. If you ever find tea leaves down here, I'm yours forever."},{"text":"You're shivering. Stew, now. Doctor's orders.","when":{"warmth":"cold"},"weight":3}]},{"id":"warmth","priority":6,"keywords":["cold","freezing","freezin","chilly","shiver","shivering","warm","warmth","toasty","hot","cozy","cosy","comfy","snug","blanket"],"replies":[{"text":"Come closer to the fire. That's what it's for."},{"text":"You're frozen. Fire, shelter, or stew. Pick all three.","when":{"warmth":"cold"},"weight":3},{"text":"Warm as toast. Biscuit's practically melting.","when":{"warmth":"warm"},"weight":2},{"text":"Inside our walls it's always warmer. Come in.","when":{"inShelter":false,"warmth":"cold"},"weight":3},{"text":"Cozy is a skill, {{player}}. You're getting good at it."}]},{"id":"feelings_sad","priority":7,"keywords":["sad","lonely","alone","upset","depressed","down","crying","cry","bad day","rough day","miss","hurt","unhappy","feel bad","feeling bad",":(","sigh"],"replies":[{"text":"Come sit by the fire. You don't have to talk."},{"text":"I'm here, {{player}}. Biscuit too. You're not alone down here."},{"text":"Bad days burn down like logs. Tomorrow we light a new one."},{"text":"Want to tell me about it? I'm a good listener. Biscuit's better."},{"text":"Rain and a sad heart. Stay in with me where it's dry.","when":{"weather":"rain"},"weight":2}]},{"id":"feelings_happy","priority":6,"keywords":["happy","glad","great","awesome","amazing","yay","woo","good day","excited","love it","lol","lmao","haha","hehe",":)",":d","nice","cool"],"replies":[{"text":"Look at that grin. It's brighter than my lantern."},{"text":"Good! Keep that feeling. Put it in your pocket for later."},{"text":"Ha! You're in a mood. I like it."},{"text":"Happy {{player}}, roaring fire. Best night in the Hollow.","when":{"fire":"roaring"},"weight":2},{"text":"Even Biscuit's wagging harder. It's catching."}]},{"id":"feelings_tired","priority":6,"keywords":["tired","sleepy","exhausted","yawn","zzz","sleepin","need sleep","so tired","worn out","knackered","beat"],"replies":[{"text":"Bed roll's waiting. Sleep, and we'll wake to morning."},{"text":"You've done plenty today, {{player}}. Rest."},{"text":"Deep night already. No wonder you're yawning.","when":{"time":"deep_night"},"weight":2},{"text":"No bed roll yet? Build one. Wood's all it takes to be comfy.","when":{"inShelter":false}},{"text":"Lie down by the fire. Biscuit will be your pillow.","when":{"fire":["lit","roaring"]},"weight":2}]},{"id":"scared","priority":8,"keywords":["scared","afraid","fear","frightened","spooky","creepy","dark","darkness","fog","foggy","mist","misty","long dark","the long dark","monster","monsters","danger","dangerous","safe","ghost","noise","scary"],"replies":[{"text":"Nothing down here will hurt you. The Long Dark is just fog that misses the light."},{"text":"The fog's soft, {{player}}. It thickens when fires die, that's all."},{"text":"Fire's low, so the fog's creeping in. A log will push it back.","when":{"fire":["low","out"]},"weight":3},{"text":"See? Roaring fire, no fog. We're safe as houses.","when":{"fire":"roaring"},"weight":2},{"text":"That noise is just drips. The Hollow talks to itself."},{"text":"Hold my hand if you want. I won't tell Biscuit."}]},{"id":"night_time","priority":4,"keywords":["night","time","late","what time","day","days","morning","dusk","midnight","clock","hour","how long","today","tonight"],"replies":[{"text":"It's day {{dayCount}}, if anyone's counting. I am."},{"text":"Daylight up top. Good time to gather.","when":{"time":"day"},"weight":2},{"text":"Dusk. The clearing goes all amber now.","when":{"time":"dusk"},"weight":2},{"text":"Night's here. Fire time, story time.","when":{"time":"night"},"weight":2},{"text":"The quiet hour. Everything's sleeping but us.","when":{"time":"deep_night"},"weight":2}]},{"id":"weather","priority":6,"keywords":["rain","raining","rainy","storm","wet","drizzle","thunder","weather","drip","drips","umbrella","sunny"],"replies":[{"text":"Rain only falls up in the clearing. Down here it's just drips."},{"text":"Listen to the rain on our roof. Isn't that the best?","when":{"weather":"rain","inShelter":true},"weight":3},{"text":"We're getting soaked! Shelter, {{player}}!","when":{"weather":"rain","inShelter":false,"area":"clearing"},"weight":3},{"text":"Clear skies. Good day to gather wood up top.","when":{"weather":"clear"}},{"text":"Rain makes the Glowmere sing. Little ripples everywhere.","when":{"weather":"rain"}}]},{"id":"jokes","priority":5,"keywords":["joke","jokes","funny","laugh","make me laugh","tell me a joke","pun","puns","silly","bored","boring"],"replies":[{"text":"Why did the mushroom get invited everywhere? He's a fungi."},{"text":"What do you call a lazy lantern? A dim-bulb. Don't tell mine."},{"text":"Biscuit tried to fetch the fog once. He's still thinking about it."},{"text":"Why don't caves get lonely? They have stalactites to hang out with."},{"text":"I'd tell you a rock joke, but you'd take it for granite."},{"text":"Knock knock. Who's there? Flint. Flint who? Flint-ly, I need more wood."}]},{"id":"about_wren","priority":6,"keywords":["about you","who are you","who r u","your past","family","lamplighter","lamplighters","lantern","your lantern","waylamp","waylamps","keepers","where are you from","home town","grandmother","grandma","age","how old","about yourself","tell me about you"],"replies":[{"text":"I'm Wren. Lamplighter's daughter from Lanternmouth. Professional fire-keeper."},{"text":"My family lit the waylamps. One by one they went out. I came to relight them."},{"text":"This lantern was my grandmother's. The crystal inside still hums."},{"text":"The Keepers lined the tunnels with lamps so nobody walked in the dark. I want that back."},{"text":"Twenty-two, sore-footed, and stubborn as flint. That's me."},{"text":"We're near where my family's lamps started. I can almost feel them.","when":{"area":"lanternmouth"},"weight":2}]},{"id":"about_cam","priority":6,"keywords":["about me","am i","do you like me","compliment","cute","pretty","beautiful","handsome","smart","you're great","ur great","youre great","you're awesome","ur awesome","best","friend","friends","bestie"],"replies":[{"text":"You, {{player}}? You build walls and pet dogs. Top marks."},{"text":"You're the best thing I found down here. Don't tell the crystals."},{"text":"Stop it, you'll make me blush, and I've only got the one face."},{"text":"You're a good friend, {{player}}. Truly."},{"text":"You're getting great at this. That shelter's proof.","when":{"inShelter":true},"weight":2}]},{"id":"love","priority":7,"keywords":["love you","i love you","ily","luv u","love u","marry","date","dating","kiss","girlfriend","crush","hug","cuddle","hold hands","like like","be mine","xoxo","<3"],"replies":[{"text":"You're a sweetheart, {{player}}. Best friend I've got down here."},{"text":"Hug? Fine. But Biscuit's getting one first. House rules."},{"text":"Steady, fire-starter. Let's keep this friendship warm, not scorched."},{"text":"I'm fond of you, truly. Like a hearth is fond of its home."},{"text":"Ha! Flattery gets you extra stew. Not a wedding."}]},{"id":"help","priority":8,"keywords":["help","hint","hints","what now","what do i do","what should i do","wat do","stuck","how do i","how to","next","goal","tips","tip","idk","dunno","confused","lost"],"replies":[{"text":"Gather wood and stone, light a fire, build a shelter. Then explore."},{"text":"Fire first, {{player}}. Wood plus flint, then tap to light it.","when":{"fire":"out"},"weight":3},{"text":"Keep that fire fed, then let's build walls around it.","when":{"fire":"low"},"weight":3},{"text":"Cold? Get near the fire or make stew from mushrooms.","when":{"warmth":"cold"},"weight":3},{"text":"Try building a roof. Rain's coming up top sometimes.","when":{"inShelter":false}},{"text":"Night's a good time to sleep. Bed roll skips to morning.","when":{"time":["night","deep_night"]},"weight":2},{"text":"Visit the Glowmere if you need a quiet sit. It's past the Hushing Pools."}]},{"id":"meta","priority":7,"keywords":["ai","bot","robot","chatbot","chatgpt","gpt","computer","game","real","real world","program","code","phone","app","npc","are you real","fake","internet","wifi"],"replies":[{"text":"Real? I'm as real as this fire, {{player}}. Feel how warm it is."},{"text":"I don't know those words. Down here it's just stone, fire, and us."},{"text":"Strange questions. Have you been sniffing glowcaps?"},{"text":"Whatever's up there, I'm glad you came down here."},{"text":"Let's not talk about the world above. Tell me about your day instead."}]},{"id":"rude","priority":7,"keywords":["stupid","dumb","idiot","shut up","stfu","hate you","hate u","ugly","annoying","useless","go away","loser","suck","sucks","you suck","u suck"],"replies":[{"text":"Ouch. Rough day? Come sit, I won't hold it against you."},{"text":"Grumpy! Biscuit forgives you instantly. I'll need a minute."},{"text":"Fair enough. I'll be here by the fire when you're feeling better."},{"text":"Hm. That sounded like a cold-and-hungry talking. Stew?"}]},{"id":"smalltalk","priority":2,"keywords":["yes","yeah","yep","yup","ya","yea","sure","ok","okay","k","kk","okie","alright","no","nope","nah","maybe","idc","hmm","hm","mhm","cool","fine"],"replies":[{"text":"Good. Glad we agree."},{"text":"Hm. Fair enough."},{"text":"Alright, {{player}}. Lead the way."},{"text":"Okay! Then let's feed this fire.","when":{"fire":["low","out"]},"weight":2},{"text":"Mhm. Biscuit nods too. He's very wise."}]},{"id":"crafting","priority":6,"keywords":["craft","crafting","make","bench","workbench","recipe","recipes","axe","pick","pickaxe","tool","tools","forge","upgrade","torch","shelves","armchair","chair","bookshelf","rug","painting","bowl","shutters","fence","gate","path","pot"],"replies":[{"text":"Most things need the bench. Campfires and the bench itself, you can make by hand."},{"text":"A stone axe chops twice as fast. Start there."},{"text":"Check the bench tabs: tools, building, cozy, food, light."},{"text":"Have and need, side by side on each card. Easy as stew."},{"text":"The old forge makes the best tools. Ember-moss is the secret.","when":{"area":"emberdeep"},"weight":3}]},{"id":"journal","priority":7,"keywords":["journal","hearth journal","goal","goals","quest","quests","chapter","task","tasks","todo","to do","objective","progress"],"replies":[{"text":"The Hearth Journal has our next steps. One page at a time."},{"text":"Each goal you finish, I'll have something to say. Fair warning."},{"text":"Edda kept a journal too. Mine has more mushrooms in it."},{"text":"Stuck on a goal? Tap it, there's a hint underneath."}]},{"id":"fishing","priority":6,"keywords":["fish","fishing","rod","cast","bait","catch","caught","lure","eel","carp","minnow","perch"],"replies":[{"text":"Fishing's at the Glowmere. Cast, wait, tap when it bites."},{"text":"Patience is the real bait, {{player}}."},{"text":"Cast near the glowing reeds. Fish love it there.","when":{"area":"glowmere"},"weight":3},{"text":"Grilled fish on the cooking pot. Simple and perfect."},{"text":"Sometimes the lake gives back old Keeper treasures. Keep fishing!"}]},{"id":"emberdeep","priority":6,"keywords":["emberdeep","ember deep","ember moss","embermoss","ember-moss","deeper dark","geothermal","hot","warm cave","forge"],"replies":[{"text":"Emberdeep is past the deepest fog. You'll need a true waylamp."},{"text":"Ember-moss glows warm for days. Perfect for lamps."},{"text":"Edda's forge is down there. My family made waylamps in it."},{"text":"Feel how warm the stone is here? It never gets cold.","when":{"area":"emberdeep"},"weight":3}]}]},"requests":{"version":1,"requests":[{"id":"req_glowcap_stew","title":"Glowcap Stew","needs":[{"item":"glowcap","count":3}],"unlockWhen":{"fire":["lit","roaring"]},"reward":{"type":"item","id":"stew","count":2},"lines":{"offer":"Bring me 3 glowcaps, {{player}}? I'll make us stew.","progress":"Any glowcaps yet? The pot's waiting.","complete":"Perfect! Stew for two. Well, three. Biscuit insists."}},{"id":"req_herb_bundle","title":"Hanging Herbs","needs":[{"item":"mushroom","count":4},{"item":"wood","count":1}],"requires":["req_glowcap_stew"],"reward":{"type":"decoration","id":"herb_bundle","count":1},"lines":{"offer":"Bring me some mushrooms and a bit of wood for a rack, and I'll hang a drying bundle. Smells like home.","progress":"Still need a few. Mossdrip has mushrooms.","complete":"Hung it by the door. Smell that!"}},{"id":"req_woven_rug","title":"A Rug for the Floor","needs":[{"item":"mushroom","count":5},{"item":"wood","count":2}],"unlockWhen":{"inShelter":true},"reward":{"type":"decoration","id":"woven_rug","count":1},"lines":{"offer":"The floor's so cold. Mushroom fibre dries soft as wool. Bring some, plus wood for a frame, and I'll weave a rug.","progress":"Weaving's slow. A few more mushrooms, please.","complete":"A rug! Our toes thank you."}},{"id":"req_dog_bed","title":"Biscuit's Bed","needs":[{"item":"wood","count":4},{"item":"mushroom","count":3}],"requires":["req_woven_rug"],"reward":{"type":"decoration","id":"biscuit_bed","count":1},"lines":{"offer":"Biscuit deserves his own bed. Wood for the frame, mushroom fibre for stuffing?","progress":"He keeps stealing my spot. Hurry.","complete":"Look at him curl up! He's never leaving."}},{"id":"req_wind_chime","title":"Crystal Wind Chime","needs":[{"item":"crystal_shard","count":3},{"item":"wood","count":1}],"requires":["req_herb_bundle"],"reward":{"type":"decoration","id":"crystal_wind_chime","count":1},"lines":{"offer":"Crystal shards ring like bells. Bring three and a bit of wood to hang them from, and I'll make a chime.","progress":"The Glowcap Galleries have shards. Listen for the hum.","complete":"Hear it? That's the Hollow singing."}},{"id":"req_second_lantern","title":"A Second Lantern","needs":[{"item":"crystal_shard","count":2},{"item":"flint","count":2},{"item":"stone","count":3}],"requires":["req_wind_chime"],"reward":{"type":"build_piece","id":"lantern_double","count":1},"lines":{"offer":"One lantern isn't enough for a home. Help me make another?","progress":"Flint and shards. Then we'll have two lights.","complete":"Two lights now. The fog won't know what hit it."}},{"id":"req_lakeside_bench","title":"Bench by the Glowmere","needs":[{"item":"wood","count":6},{"item":"stone","count":2}],"requires":["req_dog_bed"],"unlockWhen":{"area":"glowmere"},"reward":{"type":"build_piece","id":"lakeside_bench","count":1},"lines":{"offer":"I want a bench by the Glowmere. Wood and stone?","progress":"Almost. I can already picture the view.","complete":"Sit with me. Best seat in the Hollow."}}]},"lore":{"version":1,"notes":[{"id":"note_wren_arrival","kind":"note","title":"Pinned by the Fire","area":"lanternmouth","placementHint":"On a rock beside the starting campfire.","text":"Cam, if you find this before you find me: I'm Wren, the lamplighter's girl. I went ahead to look for the old waylamps. The fog's thick near the tunnel, but it's only fog. It thins wherever a fire burns. Keep yours going, and I'll follow the light back. And please feed the boxer. He keeps looking at me like I owe him dinner."},{"id":"journal_grandmother_1","kind":"journal","title":"Edda Ashby's Lamp Book, p.12","area":"lanternmouth","placementHint":"Tucked in a niche near the cave mouth, under a rusted waylamp hook.","text":"Lit forty-two lamps from Lanternmouth to the Flintseam today. My boots are wet and my knees hate me, but walking back I could see the whole tunnel glow like a string of honey. The Keepers said a lit tunnel is a kindness to strangers. I think it's a kindness to yourself, too. Wren tried to carry the oil can. She is six and very determined."},{"id":"note_flint_miner","kind":"note","title":"Miner's Scrawl","area":"flintseam","placementHint":"Scratched on a slate near the dry seam.","text":"Flint keeps a promise. Strike it once and you'll have fire. Strike it twice and you'll have a bigger fire. Strike it a third time and you'll have a lecture from the foreman about wasting flint. Signed, someone who has had that lecture."},{"id":"journal_keepers","kind":"journal","title":"Keepers' Ledger Fragment","area":"glowcap","placementHint":"Half-buried under glowcaps on a ledge.","text":"The crystals are dimmer this season. Fires take longer to catch. The fog comes in softer and stays longer. It isn't cruel, just cold, like a room nobody has sat in for a while. We will go up into the sun for a time. Leave the lamps on their hooks. Someone will come back to light them. Someone always does."},{"id":"note_mossdrip_moss","kind":"note","title":"On a Damp Page","area":"mossdrip","placementHint":"Weighted by a pebble on a mossy stump.","text":"Mossdrip moss is softer than any pillow up top. I tested this thoroughly over three naps. The drips sound like whispering, but they're only telling the stone how much they like it. If the fog rolls in while you're napping, just light a fire. It always backs away from warmth, every single time."},{"id":"journal_grandmother_2","kind":"journal","title":"Edda Ashby's Lamp Book, p.88","area":"hushing","placementHint":"On a flat stone beside the Hushing Pools.","text":"Last lamp in the Hushing Pools went out tonight. I sat with it till the end. The fog came in gently, like a cat settling on a lap. I'm not afraid of it. It's only the Hollow missing the light. One day an Ashby will come back and light these again. I hope she brings a friend. It's lonely work alone."},{"id":"note_glowmere_wish","kind":"note","title":"Message in a Jar","area":"glowmere","placementHint":"In a stoppered jar on the lakeshore.","text":"Whoever finds this: sit a while. The wisps over the Glowmere only come close when you're still. The Keepers believed every crystal in the lake was a fire someone kept burning for somebody they loved. Throw in a pebble and make a wish. Mine was for company down here. Maybe it came true."},{"id":"note_clearing_stars","kind":"note","title":"Carved in Bark","area":"clearing","placementHint":"On a birch trunk at the edge of the clearing.","text":"Up here the sky does the lamplighting. Every star is a lantern somebody hung for the ones still underground, or so my grandmother told me. On clear nights, lie in the grass and count them. On rainy nights, go home, light your hearth, and let the roof sing. Either way, you are never really in the dark. — W.A."},{"id":"journal_edda_forge","kind":"journal","title":"Edda Ashby's Lamp Book, p.140","area":"emberdeep","placementHint":"Open on the anvil of the old forge.","text":"Down in Emberdeep the stone stays warm all winter. We forged every waylamp here: brass from the old mines, crystal from the Galleries, and ember-moss to start the glow. My father taught me the tempering song. If the fires above ever go out, an Ashby can come down here and start again. The forge remembers us."},{"id":"note_embermoss","kind":"note","title":"Moss Keeper's Tag","area":"emberdeep","placementHint":"Tied to a basket beside the ember-moss beds.","text":"Ember-moss: pick gently, only from the edges, and it grows back in a week. Keep a clump in your lamp and it'll glow for days without wood. Never pile it too high in one place, or the whole room gets as warm as a summer kitchen and everyone falls asleep. That happened once. We don't talk about it."},{"id":"note_long_dark_deep","kind":"note","title":"Scratched on the Forge Wall","area":"emberdeep","placementHint":"Chalked on the warm stone above the hearth.","text":"The fog doesn't come down here. It never has. The Long Dark is cold looking for warmth, and Emberdeep has plenty, so the fog just turns around at the stair. Maybe that's what the fog really wants: somewhere warm to rest. Every fire we light up above gives it a little of that."},{"id":"journal_wren_young","kind":"journal","title":"A Child's Page","area":"emberdeep","placementHint":"Tucked inside a small brass lamp on a shelf.","text":"Grandma Edda brought me to the forge today. I'm seven. I held the tongs and only dropped them twice. She says I have lamplighter hands. I made a tiny lantern with a glowcap inside and she said it was the best one she ever saw. When I'm grown up I'm going to light every lamp in the Hollow. — Wren"}]},"biscuitFinds":{"version":1,"finds":[{"id":"flint_chips","name":"Handful of Flint Chips","flavor":"Sharp little flakes. {{biscuit}} looks very proud.","rarity":"common","weight":20,"keepsake":false,"areas":["flintseam","lanternmouth"],"givesItem":{"item":"flint","count":1}},{"id":"driftwood_bit","name":"Chewed Driftwood","flavor":"Slightly slobbery, still burns fine.","rarity":"common","weight":20,"keepsake":false,"givesItem":{"item":"wood","count":1}},{"id":"buried_mushroom","name":"Buried Mushroom","flavor":"A mushroom someone hid for later. Probably {{biscuit}}.","rarity":"common","weight":20,"keepsake":false,"areas":["mossdrip","glowcap","clearing"],"givesItem":{"item":"mushroom","count":1}},{"id":"pebble_smooth","name":"Smooth Pebble","flavor":"Round as an egg and warm from his paws.","rarity":"common","weight":20,"keepsake":false,"givesItem":{"item":"stone","count":1}},{"id":"old_bone","name":"Very Old Bone","flavor":"Not his, but he'd like it to be.","rarity":"common","weight":20,"keepsake":false},{"id":"muddy_sock","name":"Muddy Sock","flavor":"A lone sock. Its partner's fate is unknown.","rarity":"common","weight":20,"keepsake":false},{"id":"pinecone","name":"Pinecone","flavor":"Perfect for sniffing, terrible for eating. He tries anyway.","rarity":"common","weight":20,"keepsake":false,"areas":["clearing"]},{"id":"moss_clump","name":"Clump of Moss","flavor":"Soft, damp, smells like rain on stone.","rarity":"common","weight":20,"keepsake":false,"areas":["mossdrip","hushing"]},{"id":"snail_shell","name":"Empty Snail Shell","flavor":"Tiny spiral, tenant long since moved out.","rarity":"common","weight":20,"keepsake":false},{"id":"brass_button","name":"Brass Button","flavor":"Stamped with a tiny lantern. Lamplighters wore these.","rarity":"uncommon","weight":15,"keepsake":true,"placeable":true,"placeNote":"A single brass button on a scrap of cloth, glints amber in firelight."},{"id":"blue_marble","name":"Blue Glass Marble","flavor":"Swirled like the Glowmere. Some child lost it long ago.","rarity":"uncommon","weight":15,"keepsake":true,"placeable":true,"placeNote":"A blue marble resting in a little stone dish; faint inner swirl."},{"id":"crystal_sliver","name":"Crystal Sliver","flavor":"A tiny shard that hums when you hold it.","rarity":"uncommon","weight":15,"keepsake":false,"areas":["glowcap","glowmere"],"givesItem":{"item":"crystal_shard","count":1}},{"id":"tin_whistle","name":"Dented Tin Whistle","flavor":"Plays one note, very enthusiastically.","rarity":"uncommon","weight":15,"keepsake":true,"placeable":true,"placeNote":"Small dented tin whistle lying on its side."},{"id":"wax_stub","name":"Candle Stub","flavor":"Half a candle, still smells of honey.","rarity":"uncommon","weight":15,"keepsake":false},{"id":"feather_owl","name":"Soft Grey Feather","flavor":"Drifted down from the clearing on some quiet night.","rarity":"uncommon","weight":15,"keepsake":true,"areas":["clearing","lanternmouth"],"placeable":true,"placeNote":"A grey feather tucked upright in a crack or small jar."},{"id":"waylamp_key","name":"Waylamp Key","flavor":"An old brass key for a lamp case. Still turns.","rarity":"rare","weight":10,"keepsake":true,"areas":["lanternmouth","flintseam","hushing"],"placeable":true,"placeNote":"Ornate brass key hung on a nail or lying on the table, soft glint.","wrenLine":["{{player}}, that's a waylamp key! Grandma had one just like it.","Keep it safe. Somewhere down here, a lamp's waiting for it."]},{"id":"keeper_charm","name":"Keeper's Charm","flavor":"A carved stone flame on a frayed cord.","rarity":"rare","weight":10,"keepsake":true,"areas":["glowcap","glowmere","hushing"],"placeable":true,"placeNote":"Small carved stone flame pendant on a cord, draped over a shelf edge.","wrenLine":["A Keeper's charm. They gave these to travelers for warm roads.","{{biscuit}}, you clever thing. That's centuries old."]},{"id":"tiny_lantern","name":"Toy Lantern","flavor":"A palm-sized lantern with a glowcap inside. It glows softly.","rarity":"rare","weight":10,"keepsake":true,"placeable":true,"placeNote":"Miniature lantern with faint amber glow; tiny point light optional.","wrenLine":["Oh! A child's play lantern. I had one exactly like it.","Put it by the fire. It wants to be near the big ones."]}]},"itemFlavor":{"items":{"wood":"Dry driftwood from the streams above. Fire's favourite food.","stone":"Solid blue-grey stone. Walls that don't wobble.","flint":"One strike, one spark. Flint keeps its promises.","mushroom":"Brownstem mushroom. Stew's best friend.","glowcap":"Glows softly. Lovely to look at, lovelier in stew.","crystal_shard":"Hums when the fire's near, like it remembers.","stew":"Warm mushroom stew. Warms you right to your toes.","hand_lantern":"A small, plain lantern. Plenty of light to find your way."},"buildPieces":{"floor":"Keeps your toes off the cold stone.","wall":"Wood and stone, stacked with care.","window_wall":"A wall with a view of the fire.","door":"Opens, closes, keeps the fog politely outside.","roof":"Rain on top, cozy underneath.","hearth":"A home's heart. Keep it fed.","bed_roll":"Soft, warm, and skips you to morning.","lantern":"A little waylamp for your own walls.","table":"For stew bowls, keepsakes, and elbows.","chest":"Tidy storage. Biscuit can't open it. Yet."},"rewards":{"herb_bundle":"Drying mushrooms and herbs. Smells like Wren's old kitchen.","woven_rug":"Soft mushroom-fibre rug. Warm toes guaranteed.","biscuit_bed":"Biscuit's very own bed. He still prefers yours.","crystal_wind_chime":"Crystal shards that ring when the draft passes.","lantern_double":"A second lantern. Twice the glow, half the fog.","lakeside_bench":"A bench by the Glowmere. Best seat in the Hollow."}},"uiText":{"title":"Ember Hollow","tagline":"Light a fire. Find your way home.","taglineAlts":["A cozy light in the long, soft dark.","Keep the fire. Keep each other."],"subtitle":"With Wren and Biscuit","menu":{"continue":"Continue","newGame":"New Game","settings":"Settings"},"loadingTips":["Fire needs wood and flint. Keep feeding it, or it slowly burns down.","Hold on a tree or rock to gather. Wren will pitch in.","The fog thickens as fires die. A log pushes it right back.","Cold? Stand near the fire, step inside, or eat warm stew.","Put mushrooms on the fire to cook a bowl of stew.","Sleep on your bed roll to skip to a fresh morning.","Tap Biscuit for pets. He has never once said no.","Biscuit digs up little treasures. Keepsakes look lovely on a table.","Talk to Wren often. She has small requests and big stories.","Visit the Glowmere when you need a quiet sit by the water."]},"sleepLines":{"goodnight":[{"text":"Goodnight, {{player}}. Sleep warm."},{"text":"Close your eyes. I'll watch the embers."},{"text":"The fire's low. I'll tuck a log in before I sleep.","when":{"fire":["low","out"]}},{"text":"Roaring fire, full belly. Sleep like a stone.","when":{"fire":"roaring"}},{"text":"Rain drumming overhead and we're dry. Sleep tight, {{player}}.","when":{"weather":"rain","inShelter":true}},{"text":"Our own walls tonight. Sleep easy.","when":{"inShelter":true}},{"text":"Out under the rock again? Tomorrow, a roof.","when":{"inShelter":false}},{"text":"{{biscuit}} beat us to it. Listen to him snore.","when":{"biscuit":"sleeping"}},{"text":"A whole week down here, {{player}}. Goodnight, friend.","when":{"dayCountMin":7}},{"text":"Day {{dayCount}} done. Rest now."}],"goodMorning":[{"text":"Rise and shine, {{player}}. Biscuit's tail is already going."},{"text":"Up you get. The clearing's bright."},{"text":"The fire made it through the night!","when":{"fire":["lit","roaring"]}},{"text":"Fire's out. Flint and wood first, then breakfast.","when":{"fire":"out"}},{"text":"Still raining up top. A lazy morning, then.","when":{"weather":"rain"}},{"text":"Woke up dry and warm. Love this roof.","when":{"inShelter":true}},{"text":"{{biscuit}}'s still asleep. Shh, let him dream.","when":{"biscuit":"sleeping"}},{"text":"Day {{dayCount}}. We're practically Hollow folk now.","when":{"dayCountMin":10}},{"text":"Morning. I dreamt the waylamps were all lit.","when":{"dayCountMin":3}},{"text":"Stretch, yawn, stew. In that order."}]},"journal":{"version":1,"chapters":[{"id":"ch1","title":"First Light","requires":null,"intro":"The fog's thick, {{player}}, but it's only fog. Let's start where every lamplighter starts: a fire, a bench, and a decent axe.","goals":[{"id":"g1_wood","text":"Gather 5 wood","type":"gather","target":"wood","count":5,"hint":"Hold on a tree or driftwood pile.","reward":{"type":"item","id":"flint","count":1},"wrenLine":"That's a proper armful. Fire's going to love you."},{"id":"g1_fire","text":"Light a campfire","type":"craft","target":"campfire","count":1,"hint":"Campfires need 3 wood and 1 flint. No bench needed.","reward":{"type":"dialogue","id":"dlg_first_fire"},"wrenLine":"There it is. Hear the dark backing off?"},{"id":"g1_bench","text":"Place a crafting bench","type":"place","target":"crafting_bench","count":1,"hint":"Craft it by hand: 4 wood, 2 stone.","reward":{"type":"recipe","id":"hearth"},"wrenLine":"A real bench! Now we can make proper things."},{"id":"g1_stone_axe","text":"Craft a stone axe","type":"craft","target":"stone_axe","count":1,"hint":"Use the bench's Tools tab.","reward":{"type":"recipe","id":"stone_pick"},"wrenLine":"Look at you, toolmaker. Trees, beware. Gently."},{"id":"g1_pet","text":"Pet {{biscuit}}","type":"pet","target":"biscuit","count":1,"reward":{"type":"recipe","id":"dog_bowl"},"wrenLine":"He'd follow you anywhere now. He already did, really."}],"chapterReward":{"type":"decoration","id":"herb_bundle","count":1},"outro":"A fire, a bench, an axe, and a very happy dog. My grandmother would say we've made a start. Now, a roof."},{"id":"ch2","title":"A Roof Overhead","requires":"ch1","intro":"Rain finds its way down even here. Let's build walls around our fire and a roof to keep the drips off.","goals":[{"id":"g2_floor","text":"Build 4 floor pieces","type":"build","target":"floor","count":4,"reward":{"type":"item","id":"wood","count":3},"wrenLine":"Solid ground under our feet. Good start."},{"id":"g2_walls","text":"Build 4 walls","type":"build","target":["wall","window_wall"],"count":4,"hint":"Window walls count too.","reward":{"type":"item","id":"stone","count":2},"wrenLine":"Four walls. It's starting to feel like somewhere."},{"id":"g2_door","text":"Build a door","type":"build","target":"door","count":1,"reward":{"type":"dialogue","id":"dlg_door"},"wrenLine":"A door! Fog, you may knock first now."},{"id":"g2_roof","text":"Build 2 roof pieces","type":"build","target":"roof","count":2,"reward":{"type":"recipe","id":"window_shutters"},"wrenLine":"A roof. Rain says hello, and we say no thanks."},{"id":"g2_hearth","text":"Place a hearth inside","type":"place","target":"hearth","count":1,"hint":"Unlocked by placing your bench.","reward":{"type":"recipe","id":"cooking_pot"},"wrenLine":"A hearth inside our walls. That's a home, {{player}}."},{"id":"g2_sleep","text":"Sleep on a bed roll","type":"sleep","target":"bed_roll","count":1,"reward":{"type":"item","id":"stew","count":1},"wrenLine":"Slept dry and warm. Best night in ages."}],"chapterReward":{"type":"decoration","id":"crystal_wind_chime","count":1},"outro":"Walls, roof, door, hearth. We have a home now. Edda used to say a roof is just a promise you can stand under."},{"id":"ch3","title":"Home Comforts","requires":"ch2","intro":"Walls are good. But a home needs a soft place to sit, a proper bed, and somewhere to put Biscuit's treasures.","goals":[{"id":"g3_table","text":"Place a table","type":"place","target":"table","count":1,"reward":{"type":"item","id":"fiber","count":2},"wrenLine":"Somewhere for stew bowls. Civilized."},{"id":"g3_shelves","text":"Place wooden shelves","type":"place","target":"wooden_shelves","count":1,"reward":{"type":"recipe","id":"bookshelf"},"wrenLine":"Now the keepsakes have a home too."},{"id":"g3_chair","text":"Place an armchair","type":"place","target":"armchair","count":1,"reward":{"type":"dialogue","id":"dlg_armchair"},"wrenLine":"Oh, that's comfy. I'm never getting up."},{"id":"g3_rug","text":"Place a woven rug","type":"place","target":"woven_rug","count":1,"reward":{"type":"item","id":"berry","count":2},"wrenLine":"Warm toes at last. {{biscuit}} has claimed it, obviously."},{"id":"g3_bed","text":"Place a bed roll inside","type":"place","target":"bed_roll","count":1,"reward":{"type":"recipe","id":"biscuit_bed"},"wrenLine":"A proper bed indoors. Luxury, {{player}}."},{"id":"g3_cozy","text":"Reach Snug Nook coziness","type":"coziness","target":"snug_nook","count":1,"hint":"Furniture, light, warmth and decorations all count.","reward":{"type":"recipe","id":"painting"},"wrenLine":"Feel that? This place is cozy now."}],"chapterReward":{"type":"decoration","id":"wren_quilt","count":1},"outro":"Look at this place. A chair, a rug, shelves for our little treasures. I haven't felt this at home since Lanternmouth."},{"id":"ch4","title":"The Glowmere","requires":"ch3","intro":"There's a lake past the Hushing Pools that glows like the sky fell in. Bring a rod, {{player}}. I hear the fish are friendly.","goals":[{"id":"g4_visit_glowmere","text":"Visit the Glowmere","type":"visit","target":"glowmere","count":1,"hint":"Past the Hushing Pools.","reward":{"type":"recipe","id":"fishing_rod"},"wrenLine":"The Glowmere. Isn't it beautiful? Breathe it in."},{"id":"g4_rod","text":"Craft a fishing rod","type":"craft","target":"fishing_rod","count":1,"reward":{"type":"recipe","id":"lakeside_bench"},"wrenLine":"A rod! Now we just need patience. I have none."},{"id":"g4_fish","text":"Catch 3 fish","type":"fish","target":"fish","count":3,"hint":"Cast at the Glowmere and tap when it bites.","reward":{"type":"item","id":"fish","count":1},"wrenLine":"Three fish! We eat like royalty tonight."},{"id":"g4_cook","text":"Cook grilled fish","type":"cook","target":"grilled_fish","count":1,"reward":{"type":"recipe","id":"fish_stew"},"wrenLine":"Smoky and perfect. You're a natural, {{player}}."},{"id":"g4_bench","text":"Place the lakeside bench","type":"place","target":"lakeside_bench","count":1,"hint":"Place it near the Glowmere shore.","reward":{"type":"dialogue","id":"dlg_lakeside"},"wrenLine":"Sit with me. Best view in the Hollow."}],"chapterReward":{"type":"decoration","id":"glowmere_lantern_float","count":1},"outro":"Sitting here with you, I found something Edda wrote. She mentions a warm place deeper down, where the lamplighters forged their lamps. Emberdeep."},{"id":"ch5","title":"Deeper Dark","requires":"ch4","intro":"Emberdeep is past the deepest fog. No ordinary lantern will do. Let's make a true waylamp, like my family carried.","goals":[{"id":"g5_shards","text":"Gather 3 crystal shards","type":"gather","target":"crystal_shard","count":3,"reward":{"type":"item","id":"flint","count":1},"wrenLine":"These hum louder than usual. They know where we're going."},{"id":"g5_waylamp","text":"Craft a waylamp","type":"craft","target":"waylamp","count":1,"hint":"Needs the bench; unlocked when this chapter starts.","reward":{"type":"dialogue","id":"dlg_waylamp"},"wrenLine":"A real waylamp. Edda would cry. I might, too."},{"id":"g5_hold","text":"Hold the waylamp up","type":"holdItem","target":"waylamp","count":1,"reward":{"type":"item","id":"stew","count":1},"wrenLine":"See how the fog parts? Lead the way, lamplighter."},{"id":"g5_visit","text":"Enter Emberdeep","type":"visit","target":"emberdeep","count":1,"hint":"The gate past the Hushing Pools opens once you hold a waylamp.","reward":{"type":"recipe","id":"ember_lamp"},"wrenLine":"It's warm! The stone is warm. Oh, {{player}}, we found it.","unlockArea":"emberdeep"},{"id":"g5_forge","text":"Craft something at the old forge","type":"craft","target":["ember_lamp","hearthstone","ember_axe","ember_pick"],"count":1,"reward":{"type":"recipe","id":"crystal_waylamp"},"wrenLine":"The forge still works. My family's fire never really went out."},{"id":"g5_cozy","text":"Reach Warm Hearth coziness","type":"coziness","target":"warm_hearth","count":1,"reward":{"type":"dialogue","id":"dlg_ending"},"wrenLine":"Our home's as warm as Emberdeep now."}],"chapterReward":{"type":"decoration","id":"edda_lamp_book","count":1},"outro":"Every fire we light pushes the Long Dark back a little. The waylamps will glow again, {{player}}. One at a time, together."}],"dialogues":{"dlg_first_fire":"My grandmother said a first fire is a promise. I intend to keep this one.","dlg_door":"Lanternmouth doors were always painted red. Maybe we'll find berries for paint.","dlg_armchair":"When I was small I fell asleep in Edda's chair every night. She never once moved me.","dlg_lakeside":"The Keepers said every crystal in the lake was a fire someone kept for someone they loved.","dlg_waylamp":"This is how they looked, lined up all the way down. Thank you for helping me make one.","dlg_ending":"I came down here to relight the dark. I didn't expect to find a home. Or you two."}},"coziness":{"version":1,"scope":"Score counts placed pieces within the shelter footprint (or 8 m of the hearth if no roof).","categories":{"furniture":{"cap":20,"points":{"table":4,"chest":2,"wooden_shelves":3,"armchair":5,"bookshelf":4,"bed_roll":4,"crafting_bench":2,"lakeside_bench":0}},"light":{"cap":15,"points":{"lantern":3,"torch":2,"stained_crystal_lamp":5,"ember_lamp":5,"potted_glowcap":2}},"warmth":{"cap":20,"points":{"hearth":10,"campfire":5,"hearthstone":6},"bonus":{"fireLit":4,"fireRoaring":6}},"decorations":{"cap":25,"points":{"herb_bundle":3,"crystal_wind_chime":3,"painting":6,"dog_bowl":3,"biscuit_bed":4,"brass_kettle":3,"wren_quilt":4,"glowmere_lantern_float":3,"edda_lamp_book":4,"keepsake":2}},"floor":{"cap":10,"points":{"woven_rug":6,"floor":0.5,"stone_path":0.5}}},"rules":["Each category is capped; points above the cap are ignored.","A repeated piece scores full points for the first 2 copies, then 0 (anti-spam), except floor and stone_path.","'keepsake' means any placed keepsake from biscuit_finds or fishing.","Recompute on place/remove and on fire state change; announce tier changes only upward."],"tiers":[{"id":"cold_camp","name":"Cold Camp","minScore":0,"unlock":{"type":"recipe","id":"herb_bundle"},"wren":["It's a start, {{player}}. A fire and a hope.","A bit bare. We'll fix that."],"biscuit":["sits close to Cam, ears slightly back","curls tight by the fire"]},{"id":"snug_nook","name":"Snug Nook","minScore":15,"unlock":{"type":"recipe","id":"potted_glowcap"},"wren":["Feel that? It's getting snug in here.","I could get used to this."],"biscuit":["trots a happy lap of the shelter","flops on his side by the hearth"]},{"id":"warm_hearth","name":"Warm Hearth","minScore":35,"unlock":{"type":"recipe","id":"stained_crystal_lamp"},"wren":["This is a real home now. Warm all through.","Edda would have loved this room.","I keep smiling for no reason. It's the room's fault."],"biscuit":["sprawls belly-up on the rug","brings a keepsake and drops it at Cam's feet"]},{"id":"cozy_cottage","name":"Cozy Cottage","minScore":55,"unlock":{"type":"decoration","id":"wren_quilt"},"wren":["The coziest place in the whole Hollow, and we built it.","Don't tell the Glowmere, but I like it here more."],"biscuit":["snores loudly in his bed","does a slow, happy zoomie and collapses on the rug"]},{"id":"ember_home","name":"Ember Home","minScore":75,"unlock":{"type":"decoration","id":"ember_garland"},"wren":["The fog doesn't even come near anymore. We did that, {{player}}.","A lamplighter's home. Finally.","Every waylamp in the Hollow would be jealous."],"biscuit":["sits by the hearth, chest out, guarding his home","rolls over for belly rubs whenever Cam walks past"]}]},"m2Lines":{"version":1,"cooldowns":{"globalSec":20,"perTriggerSec":60},"triggers":{"craft_success":{"any":["Nicely made, {{player}}.","Look at that. Proper craftsmanship.","Another thing we didn't have this morning."],"tools":["A good tool makes the work half as hard.","Sharp and sturdy. Gathering just got easier.","That'll save your arms some ache."],"building":["More house! I love more house.","That'll fit right in.","Stack it, snap it, call it home."],"cozy":["Oh, that's lovely. Put it somewhere I can see it.","Cozier by the minute.","Biscuit approves. He sniffed it."],"food":["Smells wonderful. Is it ready yet?","Warm food, warm hearts. Pass a bowl.","Chef {{player}}, at your service."],"light":["More light, less fog. That's the lamplighter way.","Look how it glows. Edda would grin.","The dark just took a step back."]},"craft_first_time":{"stone_axe":["Your first real tool! Trees, consider yourselves warned."],"fishing_rod":["A rod! Let's go find something that swims."],"painting":["Is that me? Is that Biscuit's nose? I love it. Hang it by the fire."],"dog_bowl":["His own bowl! Biscuit, look. You're a dog of property now."],"waylamp":["A true waylamp. I haven't held one since I was little."],"cooking_pot":["A proper pot! No more stew in a hollow stone."]},"bench_placed":["A real crafting bench. Now we're in business.","Every lamplighter needs a bench. Now you have one.","That's where the good stuff gets made."],"goal_complete":["One more page in the journal.","Done! Tick it off, {{player}}.","Look at us, getting things done.","Edda kept a journal like that. She'd be proud."],"chapter_complete":["A whole chapter. Shall we see what's next?","That's a chapter closed. And a new one waiting.","We did it. On to the next page."],"journal_opened":["The Hearth Journal. Let's see what's next.","Reading ahead? I like a planner.","Every page is a little more home."],"fish_bite":["Something's biting! Now!","Tug! Tug, {{player}}!","Ooh, a nibble. Steady..."],"fish_caught":["Got one! Look at it wiggle.","Supper's sorted.","Nice catch! Biscuit's drooling already."],"fish_rare":["That's no fish. That's treasure!","Oh, {{player}}! Bring that up here, let me see!","The Glowmere's giving gifts tonight."],"fish_miss":["It got away. Plenty more in the lake.","Next time. The fish are just shy.","So close! Patience, lamplighter."],"enter_emberdeep":["It's warm! The stone itself is warm.","Emberdeep. Edda wrote about this place.","Smell that? Ember-moss. Like a hearth that never goes out.","No fog at all down here. Just warmth."],"forge_used":["The old forge still sings.","My family stood right here making lamps.","Hot work. Mind your fingers."],"tool_upgrade":["Forge-tempered! That'll last forever.","Better tools, easier days.","Look at that edge. Edda's forge does good work."]}}};
